export const poissonDisc = (bounds, radius = 10, searches = 10, maxPoints = 100000) => {
    const cellSize = radius / Math.sqrt(2); // grid cell size, radius/sqrt(grid dimensions)
    const grid = new FlatGrid(bounds, 0, 0, cellSize);
    const active = [];
    let points = [];

    let pointCount = 0;

    const seedPoint = { x: 1, y: 1 };
    active.push(seedPoint);
    grid.setValue(grid.xToCol(seedPoint.x), grid.yToRow(seedPoint.y), seedPoint);

    const getSample = (fromPosition) =>
        random2dVector()
            .setMag(randomNumberBetween(radius, radius * 2))
            .add(fromPosition);

    // check grid around and true if there is a point that's too close
    const isInNeighborHood = (sample, sampleCol, sampleRow) => {
        for (let i = -1; i <= 1; i++) {
            for (let j = -1; j <= 1; j++) {
                const neighbor = grid.getValue(sampleCol + i, sampleRow + j);
                if (neighbor) {
                    const distanceBetween = Vector.dist(sample, pointObjectToVector(neighbor));
                    if (distanceBetween < radius) {
                        return true;
                    }
                }
            }
        }
        return false;
    };

    const next = () => {
        const rndActiveIdx = randomWholeBetween(0, active.length);
        const currentActive = pointObjectToVector(active[rndActiveIdx]);
        let didFindPoint = false;

        for (let n = 0; n < searches; n++) {
            const sample = getSample(currentActive);
            const sampleCol = grid.xToCol(sample.x);
            const sampleRow = grid.yToRow(sample.y);

            if (
                grid.pointInBounds(sample.x, sample.y) &&
                !grid.hasValue(sampleCol, sampleRow) &&
                !isInNeighborHood(sample, sampleCol, sampleRow)
            ) {
                didFindPoint = true;
                const p = vectorToPointObject(sample);
                grid.setValue(sampleCol, sampleRow, p);
                active.push(p);
                points.push(p);
            }
        }

        if (!didFindPoint) {
            active.splice(rndActiveIdx, 1);
        }

        if (++pointCount > maxPoints) return false;

        return active.length > 0;
    };

    const getPoints = () => points;
    const getActive = () => active;
    const getGrid = () => grid;

    const clearPoints = () => (points = []);

    const getOffsetPoints = () =>
        points.map((p) => {
            p.x += bounds.x;
            p.y += bounds.y;
            return p;
        });

    const doNext = (runs = 100) => {
        let isNext = true;
        let itr = 0;
        while (itr++ < runs && isNext) {
            isNext = next();
        }
        return isNext;
    };

    const fill = () => {
        // console.time('poissonDisc');
        let isNext = true;
        while (isNext) {
            isNext = next();
        }
        // console.timeEnd('poissonDisc');
        return getOffsetPoints();
    };

    return {
        getOffsetPoints,
        getPoints,
        getActive,
        getGrid,
        clearPoints,
        doNext,
        next,
        fill,
    };
};

