/*
The grid must take a list of points.
The cell size must be computed from the maximum the radius can be.
The neighbourhood function should iterate through all points in every cell of a point’density0 neighbourhood.
Where a new point is generated, check the grey scale value of the image at that point, and calculate a minimum distance from the grey scale value:
 */
// return between 0 and 1
const fixedDistance = (s) => 0.5;

export const poissonDiscVariable = (
    bounds,
    minRadius = 5,
    maxRadius = 10,
    distanceFn,
    distFraction = 0.5,
    searches = 30
) => {
    distanceFn = distanceFn || fixedDistance;

    const midRadius = midNumber(minRadius, maxRadius);

    const cellSize = maxRadius / Math.sqrt(2); // 1.41421356237
    const grid = new FlatGrid(bounds, 0, 0, cellSize, []);

    const active = [];
    let points = [];

    const maxPoints = 1000000;
    let pointCount = 0;

    const seedPoint = { x: Math.floor(bounds.w / 2), y: 0 };
    active.push(seedPoint);
    grid.setValue(grid.xToCol(seedPoint.x), grid.yToRow(seedPoint.y), seedPoint);

    // console.log(`${minRadius} -> ${maxRadius}, Mid rad ${midRadius}, cell size ${cellSize}`);

    // Sample is supposed to be between min and 2*min, but when the max distance is too high, this produces blank results
    // or areas in patters. increasing the max size mitigates this
    const sampleMax = Math.max(minRadius * 2, maxRadius);
    const getSample = (fromPosition) =>
        random2dVector().setMag(randomNumberBetween(minRadius, sampleMax)).add(fromPosition);

    // non-uniform, favours points closer to the inner ring, leads to denser packings
    // const generateRandomPointAround = ({ x, y }, distance) => {
    //     const r1 = Math.random();
    //     const r2 = Math.random();
    //     const radius = distance * (r1 + 1); // random radius between distance and 2 * distance
    //     const angle = 2 * Math.PI * r2; // random angle
    //     const newX = x + radius * Math.cos(angle);
    //     const newY = y + radius * Math.sin(angle);
    //     return new Vector(newX, newY);
    // };

    // check grid around and true if there is a point that'density0 too close
    // The neighbourhood function should iterate through all points in every cell of a point’density0 neighbourhood.
    const isSampleTooClose = (sample, sampleCol, sampleRow, minDistance) => {
        let tooClose = false;
        minDistance *= distFraction;

        for (let i = -1; i <= 1; i++) {
            for (let j = -1; j <= 1; j++) {
                if (grid.contains(sampleCol + i, sampleRow + j)) {
                    grid.getValue(sampleCol + i, sampleRow + j).forEach((neighbor) => {
                        const distanceBetween = Vector.dist(sample, pointObjectToVector(neighbor));
                        // console.log(`Neighbor ${neighbor.toString()}, sample ${sample}, minDistance ${distanceBetween}`);
                        // console.log(`minDistance ${minDistance}, between ${distanceBetween}, ${minDistance > distanceBetween}`);
                        if (minDistance > distanceBetween) {
                            tooClose = true;
                        }
                    });
                }
            }
        }

        return tooClose;
    };

    const next = () => {
        if (!active.length) return;

        const rndActiveIdx = randomWholeBetween(0, active.length);
        const currentActive = pointObjectToVector(active[rndActiveIdx]);
        let didFindPoint = false;

        for (let n = 0; n < searches; n++) {
            const sample = getSample(currentActive);
            // const sample = generateRandomPointAround(currentActive, minRadius);
            const sampleCol = grid.xToCol(sample.x);
            const sampleRow = grid.yToRow(sample.y);

            // distFn values between 0 and 1 will lerp between min and max radii
            const minDistance = minRadius + distanceFn(sample) * (maxRadius - minRadius);

            // console.log(sample.x, sample.y, sampleCol, sampleRow, `grid cell? ${grid.contains(sampleCol, sampleRow)}`);

            if (grid.contains(sampleCol, sampleRow) && !isSampleTooClose(sample, sampleCol, sampleRow, minDistance)) {
                didFindPoint = true;
                const p = vectorToPointObject(sample);
                grid.setValue(sampleCol, sampleRow, p);
                active.push(p);
                points.push(p);
            }
        }

        if (!didFindPoint) {
            active.splice(rndActiveIdx, 1);
        }

        if (++pointCount > maxPoints) return false;

        if (active.length === 0) {
            // console.log('Poisson done');
        }

        return active.length > 0;
    };

    const getPoints = () => points;
    const getActive = () => active;
    const getGrid = () => grid;

    const clearPoints = () => (points = []);

    const getOffsetPoints = () =>
        points.map((p) => {
            p.x += bounds.x;
            p.y += bounds.y;
            return p;
        });

    const doNext = (runs = 100) => {
        let isNext = true;
        let itr = 0;
        while (itr++ < runs && isNext) {
            isNext = next();
        }
        return isNext;
    };

    const fill = () => {
        // console.time('poissonDisc');
        let isNext = true;
        while (isNext) {
            isNext = next();
        }
        // console.timeEnd('poissonDisc');
        return getOffsetPoints();
    };

    return {
        getOffsetPoints,
        getPoints,
        getActive,
        getGrid,
        clearPoints,
        next,
        doNext,
        fill,
    };
};

