export const getPointsForAreaFill = (bounds, min = 2, max = 10, freq = 0) => {
    const simplexFn = simplexNoise2d(freq, 1, false);
    const distanceFn = ({ x, y }) => mapRange(-1, 1, 0, 1, simplexFn(x, y));
    const poisson = poissonDiscVariable(bounds, min, max, distanceFn, 0.9, 50);
    return poisson.fill();
};
