export const segment = (x1, y1, x2, y2) => {
    const start = new Vector(x1, y1);
    const end = new Vector(x2, y2);
    const mp = midpoint(start, end);
    const mid = new Vector(mp.x, mp.y);
    const orientation = pointsOrientation(start, end);
    const length = pointDistance(start, end);
    return { start, end, orientation, mid, length };
};

// https://bytes.com/topic/c/answers/221393-generate-random-points-line
export const randomVectorOnSegment = (seg, normal = true) => {
    const t = normal ? randomNormalNumberBetween(0, 1) : randomNumberBetween(0, 1);
    // const x = (1 - t) * seg.start.x + t * seg.end.x;
    // const y = (1 - t) * seg.start.y + t * seg.end.y;
    const x = seg.start.x + t * (seg.end.x - seg.start.x);
    const y = seg.start.y + t * (seg.end.y - seg.start.y);
    return new Vector(x, y);
};

export const segmentOrientation = ({ start, end }) => pointsOrientation(start, end);

export const segmentFromPoint = (p1, p2) => segment(p1.x, p1.y, p2.x, p2.y);

export const segmentsFromPoints = (points) => {
    const seg = [];
    for (let i = 0; i < points.length - 1; i++) {
        const next = i + 1;
        seg.push(segment(points[i][0], points[i][1], points[next][0], points[next][1]));
    }
    return seg;
};

export const segArrayToPointsArray = (segs) =>
    segs.reduce((acc, s) => {
        const p = [
            [s.start.x, s.start.y],
            [s.end.x, s.end.y],
        ];
        acc = acc.concat(p);
        return acc;
    }, []);

export const segmentsIntersect = (a, b) =>
    linesIntersect(a.start.x, a.start.y, a.end.x, a.end.y, b.start.x, b.start.y, b.end.x, b.end.y);

// Remove every skip points from a segment to simplify
export const trimSegments = (segs, skip = 2) =>
    segs.reduce((acc, s, i) => {
        if (i === 0 || i === segs.length - 1) {
            acc.push(s);
        } else if (i % skip === 0) {
            acc.push(s);
        }
        return acc;
    }, []);

// TODO offset side base on segment orientation
export const getSegmentOffsetFromSegment = (seg, offset, direction = 1) => {
    // getMap a vector perpendicular 90deg to the angle of the segment
    const normalVector = uvFromAngle(seg.orientation + 1.5708).setMag(offset * direction);
    const offsetStart = seg.start.add(normalVector);
    const offsetEnd = seg.end.add(normalVector);

    // const offsetMid = seg.mid.add(normalVector);
    // const offsetMid = randomVectorOnSegment(seg).add(normalVector);
    // const s2m = segmentFromPoint(seg.start, offsetMid);
    // const m2e = segmentFromPoint(offsetMid, seg.end);

    return segmentFromPoint(offsetStart, offsetEnd);
};

