export const roughenSegments = (segPoly, itterations = 2, maxV = 0.4, spread = 0) => {
    const roughSegment = (seg) => {
        const rMagMax = seg.length * seg.variance;
        const magDirection = chance(2) ? 1 : -1;
        const rMag = randomNormalNumberBetween(0.1, rMagMax) * magDirection; // + spread
        // getMap a vector perpendicular 90deg to the angle of the segment
        const normalVector = uvFromAngle(seg.orientation + 1.5708).setMag(rMag);

        // const offsetMid = seg.mid.add(normalVector);
        const offsetMid = randomVectorOnSegment(seg, true).add(normalVector);
        const s2m = segmentFromPoint(seg.start, offsetMid);
        const m2e = segmentFromPoint(offsetMid, seg.end);

        s2m.variance = seg.variance + spread;
        m2e.variance = seg.variance + spread;
        return [s2m, m2e];
    };

    const roughPolySegments = (segments, currentIttr = 0) => {
        let finalPoly = [];
        segments.forEach((s) => {
            // Greater max variance = more spread
            s.variance = s.variance || randomNumberBetween(0, maxV);
            finalPoly = finalPoly.concat(roughSegment(s));
        });
        if (++currentIttr > itterations) {
            return finalPoly;
        }
        return roughPolySegments(finalPoly, currentIttr);
    };

    return roughPolySegments(segPoly);
};

export const extendSegments = (segs, offset) => {
    const first = segs[0];
    const last = segs[segs.length - 1];

    if (!first || !last) return segs;

    const newFirstSeg = { ...first };
    const newLastSeg = { ...last };
    try {
        newFirstSeg.start = newFirstSeg.start.add(uvFromAngle(first.orientation).setMag(offset * -1));
        newFirstSeg.end = first.start;
        newLastSeg.start = last.end;
        newLastSeg.end = newLastSeg.end.add(uvFromAngle(last.orientation).setMag(offset));
    } catch (e) {
        console.warn('Extend segments', e);
        console.log(newFirstSeg, newLastSeg);
        console.log(first, last);
        return segs;
    }

    segs.unshift(newFirstSeg);
    segs.push(newLastSeg);

    return segs;
};

export const connectSegments = (segs) =>
    segs.map((s, i) => {
        if (i === segs.length - 1) {
            return s;
        }
        const next = segs[i + 1];

        const distance = pointDistance({ x: s.end.x, y: s.end.y }, { x: next.start.x, y: s.start.y });
        if (distance > 1) {
            s.end = new Vector(next.start.x, next.start.y);
        }
        return s;
    });

