    // x = 0, y = 0,
    image(src, successCb, failureCb) {
        const show = (x = 0, y = 0) => {
            bitmap.x = x;
            bitmap.y = y;
            bitmap.bounds = new Rectangle(x, y, bitmap.width, bitmap.height);
            this.context.drawImage(bitmap.image, x, y);
            return bitmap.bounds;
        };

        const bitmap = {
            id: this.bitmaps.length,
            src,
            image: new Image(),
            x: 0,
            y: 0,
            bounds: null,
            width: 0,
            height: 0,
            show,
        };

        const onLoad = (e) => {
            // console.log('image loaded', this, bitmap);
            bitmap.width = bitmap.image.naturalWidth;
            bitmap.height = bitmap.image.naturalHeight;
            if (successCb) successCb(bitmap);
        };

        bitmap.image.addEventListener('load', onLoad);

        bitmap.image.src = src;
        bitmap.width = bitmap.image.width;
        bitmap.height = bitmap.image.height;
        bitmap.bounds = new Rectangle(0, 0, bitmap.width, bitmap.height);
        this.bitmaps.push(bitmap);
        return bitmap;
    }

