    scaleAreaToCanvas(bounds, res = 100, xoff = 0, yoff = 0) {
        if (bounds.w === 0) {
            console.warn('scaleAreaToCanvas, bounds width is 0');
            return;
        }

        const round = (n) => Math.round(n);

        const capture = this.context.getImageData(bounds.x, bounds.y, bounds.w, bounds.h);

        const capturePxColor = (x, y) => tinycolor(this.pixelColorFromImageData(capture, x, y));

        const { width, height } = this.canvas;

        const xres = res || Math.round(width / 4);
        const yres = res || Math.round(height / 4);

        const colw = width / xres;
        const rowh = height / yres;

        const xratio = width / bounds.w;
        const yratio = height / bounds.h;

        this.push();
        this.noStroke();
        for (let i = 0; i < xres; i++) {
            for (let j = 0; j < yres; j++) {
                const x = i * colw;
                const y = j * rowh;
                const dx = Math.round(x / xratio);
                const dy = Math.round(y / yratio);
                this.fill(capturePxColor(dx, dy));
                this.rect(round(x + xoff), round(y + yoff), round(colw), round(rowh));
            }
        }
        this.refreshImageData();
        this.pop();
    }

    //------------------------------------------------------------------------------------------------------------------
    //------------------------------------------------------------------------------------------------------------------
    //------------------------------------------------------------------------------------------------------------------

    thresholdAsPoints(res = 100, threshold = 128, inv = false) {
        const testFn = (g) => (inv ? g < threshold : g > threshold);

        const points = [];
        const { width, height } = this.canvas;

        const colw = Math.round(width / res);
        const rowh = Math.round(height / res);

        for (let i = 0; i < res; i++) {
            for (let j = 0; j < res; j++) {
                const x = i * colw;
                const y = j * rowh;
                if (testFn(this.pixelAverageGrey(x, y))) {
                    points.push([x, y]);
                }
            }
        }

        return points;
    }
