export const setAttractorValues = (a, b = 0, c = 0, d = 0, e = 0, f = 0) => {
    attractorVarA = a;
    attractorVarB = b;
    attractorVarC = c;
    attractorVarD = d;
    attractorVarE = e;
    attractorVarF = f;
};

// http://paulbourke.net/fractals/clifford/
// https://fronkonstin.com/2017/11/07/drawing-10-million-points-with-ggplot-clifford-attractors/
export const cliffordAttractorRadians = (bounds, offset = 0.5, scale = 0.01) => (x, y) => {
    scale = scale || attractorScale;
    x = (x - bounds.w * offset) * scale;
    y = (y - bounds.h * offset) * scale;
    const x1 = Math.sin(attractorVarA * y) + attractorVarC * Math.cos(attractorVarA * x);
    const y1 = Math.sin(attractorVarB * x) + attractorVarD * Math.cos(attractorVarB * y);
    return Math.atan2(y1 - y, x1 - x);
};

// http://paulbourke.net/fractals/peterdejong/
export const jongAttractorRadians = (bounds, offset = 0.75, scale = 0.01) => (x, y) => {
    scale = scale || attractorScale;
    x = (x - bounds.w * offset) * scale;
    y = (y - bounds.h * offset) * scale;
    const x1 = Math.sin(attractorVarA * y) - Math.cos(attractorVarB * x);
    const y1 = Math.sin(attractorVarC * x) - Math.cos(attractorVarD * y);
    return Math.atan2(y1 - y, x1 - x);
};

