import { greyValueToRGB } from '../color/palettes';
import { mapRange } from '../math/math';
import { randomValue, randomWholeBetween } from '../math/random';

const lerp255 = (min, max, value) => mapRange(0, 255, min, max, value);

export const getHeightAtPosition = (terrain, bounds, x, y) => {
    const brightness = terrain.getBrightnessAt(bounds, x, y);
    const theta = lerp255(-1, 1, brightness);
    const height = lerp255(-10, 10, brightness);
    return { brightness, theta, height };
};

export class Terrain {
    constructor(detail, roughness) {
        this.detail = detail;
        this.roughness = roughness;
        this.size = Math.pow(2, detail) + 1;
        this.max = this.size - 1;
        this.map = new Array(this.size * this.size); // new Float32Array(this.size * this.size);

        // console.log('Terrain size: ', this.size);
    }

    getMap(x, y) {
        if (x < 0 || x > this.max || y < 0 || y > this.max) return -1;
        return this.map[x + this.size * y];
    }

    setMap(x, y, val) {
        this.map[x + this.size * y] = val;
    }

    divide(size) {
        let x;
        let y;
        const half = size / 2;
        const scale = this.roughness * size;
        if (half < 1) return;

        for (y = half; y < this.max; y += size) {
            for (x = half; x < this.max; x += size) {
                this.square(x, y, half, randomValue() * scale * 2 - scale);
            }
        }
        for (y = 0; y <= this.max; y += half) {
            for (x = (y + half) % size; x <= this.max; x += size) {
                this.diamond(x, y, half, randomValue() * scale * 2 - scale);
            }
        }
        this.divide(size / 2);
    }

    average(values) {
        const valid = values.filter((val) => val !== -1);
        const total = valid.reduce((sum, val) => sum + val, 0);
        return total / valid.length;
    }

    square(x, y, size, offset) {
        const ave = this.average([
            this.getMap(x - size, y - size), // upper left
            this.getMap(x + size, y - size), // upper right
            this.getMap(x + size, y + size), // lower right
            this.getMap(x - size, y + size), // lower left
        ]);
        this.setMap(x, y, ave + offset);
    }

    diamond(x, y, size, offset) {
        const ave = this.average([
            this.getMap(x, y - size), // top
            this.getMap(x + size, y), // right
            this.getMap(x, y + size), // bottom
            this.getMap(x - size, y), // left
        ]);
        this.setMap(x, y, ave + offset);
    }

    generate() {
        this.setMap(0, 0, this.max);
        this.setMap(this.max, 0, this.max / 2);
        this.setMap(this.max, this.max, 0);
        this.setMap(0, this.max, this.max / 2);

        this.divide(this.max);

        return this.map;
    }

    brightness(x, y, slope) {
        if (y === this.max || x === this.max) return 0;
        return Math.trunc(slope * 50) + 128;
    }

    getBrightnessAt(bounds, x, y) {
        const size = this.size - 1; // -1 to remove black edge on right/bottom of map
        const i = Math.floor(x / (bounds.w / size));
        const j = Math.floor(y / (bounds.h / size));
        const val = this.getMap(i, j);
        return this.brightness(i, j, this.getMap(i + 1, j) - val);
    }

    draw(rcanvas, bounds) {
        // let { x } = bounds;
        let { y } = bounds;
        const maxX = bounds.x2;
        const maxY = bounds.y2;

        const size = this.size - 1; // remove black edge on right/bottom of map

        const xstep = bounds.w / size;
        const ystep = bounds.h / size;

        rcanvas.push();
        rcanvas.noStroke();
        for (let j = 0; j < size; j++) {
            let { x } = bounds;
            for (let i = 0; i < size; i++) {
                const val = this.getMap(i, j);

                const brightness = this.brightness(i, j, this.getMap(i + 1, j) - val);

                rcanvas.fill(greyValueToRGB(brightness));
                // rcanvas.point(i, j);
                rcanvas.rect(x, y, xstep, ystep);
                x += xstep;
            }
            y += ystep;
        }

        rcanvas.pop();
    }
}

export const createTerrain = (bounds, detail, roughness) => {
    const terrain = new Terrain(detail, roughness);
    terrain.generate();

    const getTerrain = function () {
        return terrain;
    };

    const getHeightAt = function (x, y) {
        getHeightAtPosition(terrain, bounds, x, y);
    };

    return {
        getTerrain,
        getHeightAt,
    };
};
