import { Vector } from './Vector';
import { cos, degreesToRadians, lerp, sin, snapNumber } from './math';
import { getCurvePoints } from './curve-calc';

export const point = (x, y) => ({ x, y });

export const pointA = (x, y) => [x, y];

export const getPointA = (p) => (Array.isArray(p) ? p : [p.x, p.y]);
export const getPointO = (p) => (Array.isArray(p) ? { x: p[0], y: p[1] } : p);

export const midPoint = (a, b) => Math.round((b - a) / 2) + a;

export const snapPointPA = (p, s) => [snapNumber(s, p[0]), snapNumber(s, p[1])];
export const snapPointPO = (p, s) => ({ x: snapNumber(s, p.x), y: snapNumber(s, p.y) });

export const pointObjectToPointArray = (p) => [p.x, p.y];
export const pointArrayToPointObject = (a) => ({ x: a[0], y: a[1] });
export const pointObjectToVector = (a) => new Vector(a.x, a.y);
export const pointArrayToVector = (a) => new Vector(a[0], a[1]);
export const vectorToPointArray = (v) => [v.x, v.y];
export const vectorToPointObject = (v) => ({ x: v.x, y: v.y });
// [[x,y]] => [{x:x,y:y}]
export const arrayPointArrayToObjectArray = (arry) => arry.map((a) => pointArrayToPointObject(a));
// [[x,y]] => [Vector{x:x,y:y}]
export const arrayPointArrayToVectorArray = (arry) => arry.map((a) => pointArrayToVector(a));
export const arrayVectorToPointArray = (arry) => arry.map((a) => vectorToPointArray(a));

// [[x,y]] => [x1, y1,  x2, y2, ... xn, yn]
export const flattenPointArray = (arry) =>
    arry.reduce((acc, p) => {
        if (p) {
            acc.push(p[0]);
            acc.push(p[1]);
        }

        return acc;
    }, []);

// [x1, y1,  x2, y2, ... xn, yn] => [[x,y]]
export const unflattenPointArray = (arry) => {
    const points = [];
    for (let i = 0; i < arry.length; i += 2) {
        points.push([arry[i], arry[i + 1]]);
    }
    return points;
};

export const uvPointToCanvas = ({ margin = 0, u, v, width, height }) => ({
    x: lerp(margin, width - margin, u),
    y: lerp(margin, height - margin, v),
});

export const pointDistance = (pointA, pointB) => {
    const dx = pointA.x - pointB.x;
    const dy = pointA.y - pointB.y;
    return Math.sqrt(dx * dx + dy * dy);
};

export const midpoint = (pointA, pointB) => ({ x: (pointA.x + pointB.x) / 2, y: (pointA.y + pointB.y) / 2 });

// https://stackoverflow.com/questions/13043945/how-do-i-calculate-the-position-of-a-point-in-html5-canvas-after-rotation
export const pointRotateCoord = (point, angle) => ({
    x: point.x * cos(angle) - point.y * sin(angle),
    y: point.y * cos(angle) + point.x * sin(angle),
});

// https://www.khanacademy.org/computing/computer-programming/programming-natural-simulations/programming-angular-movement/a/pointing-towards-movement
export const pointAngleFromVelocity = ({ velocityX, velocityY }) => Math.atan2(velocityY, velocityX);

// Scale up point grid and center in the canvas
export const scalePointToCanvas = (canvasWidth, canvasHeight, width, height, zoomFactor, x, y) => {
    const particleXOffset = canvasWidth / 2 - (width * zoomFactor) / 2;
    const particleYOffset = canvasHeight / 2 - (height * zoomFactor) / 2;
    return {
        x: x * zoomFactor + particleXOffset,
        y: y * zoomFactor + particleYOffset,
    };
};

export const pointsOrientation = (a, b) => Math.atan2(b.y - a.y, b.x - a.x);

export const pointsFromSegment = (seg) => {
    const points = [];
    for (let i = 0; i < seg.length; i++) {
        points.push([seg[i].start.x, seg[i].start.y]);
        points.push([seg[i].end.x, seg[i].end.y]);
    }
    return points;
};

export const trimPointArray = (points, skip = 2) =>
    points.reduce((acc, s, i) => {
        if (i === 0 || i === points.length - 1) {
            acc.push(s);
        } else if (i % skip === 0) {
            acc.push(s);
        }
        return acc;
    }, []);

export const createSplineFromPointArray = (points) => unflattenPointArray(getCurvePoints(flattenPointArray(points)));

// Menger curvature of a triple of points in n-dimensional Euclidean space Rn is the reciprocal of
// the radius of the circleOld that passes through the three points
export const mengerCurvature = (p1, p2, p3) => {
    // https://stackoverflow.com/questions/41144224/calculate-curvature-for-3-points-x-y
    // possible alternate https://www.mathsisfun.com/geometry/herons-formula.html
    const triangleArea2 = (a, b, c) => (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);

    const t4 = 2 * triangleArea2(p1, p2, p3);
    const la = pointDistance(p1, p2);
    const lb = pointDistance(p2, p3);
    const lc = pointDistance(p3, p1);
    return t4 / (la * lb * lc);
};

/*
const averageCurve =
                averageMengerCurvature(getNeighboringPoints(settings.outlineNeighborSize, i, midPoints)) *
                settings.outlineCurveMultiplier;
            const curveDirection = averageCurve < 0 ? 1 : -1;
 */
export const getNeighboringPoints = (length, startIndex, pointsArry) => {
    const min = startIndex < length ? 0 : startIndex - length;
    const max = startIndex > pointsArry.length - length ? pointsArry.length : startIndex + length;
    return pointsArry.slice(min, max);
};

// Average Menger curvature of the segments
// https://stackoverflow.com/questions/41144224/calculate-curvature-for-3-points-x-y
// possible alternate https://www.mathsisfun.com/geometry/herons-formula.html
export const averageMengerCurvature = (points) => {
    const sum = points.reduce((diffs, point, i) => {
        const prev = i - 1;
        const next = i + 1;
        if (prev >= 0 && next < points.length) {
            diffs += mengerCurvature(points[prev], point, points[next]);
        }
        return diffs;
    }, 0);
    return degreesToRadians(sum / points.length);
};

// https://www.youtube.com/watch?v=01E0RGb2Wzo
// point -> [x,y]
// poly -> [[x,y],[x,y],[x,y]...]
export const pointInsidePolygon = (pt, polygon) => {
    const n = polygon.length;
    let count = 0;
    const x = pt[0];
    const y = pt[1];
    for (let i = 0; i < n - 1; ++i) {
        const side = { a: { x: polygon[i][0], y: polygon[i][1] }, b: { x: polygon[i + 1][0], y: polygon[i + 1][1] } };
        const x1 = side.a.x;
        const y1 = side.a.y;
        const x2 = side.b.x;
        const y2 = side.b.y;

        if (y < y1 != y < y2 && x < ((x2 - x1) * (y - y1)) / (y2 - y1) + x1) {
            count += 1;
        }
    }

    return count % 2 !== 0;
};

