const maxParticleHistory = 30;

export const createRandomParticleValues = (minx, maxx, miny, maxy) => {
    const vel = 1;
    const radius = randomNumberBetween(5, 10);
    return {
        radius,
        x: randomNumberBetween(minx, maxx),
        y: randomNumberBetween(miny, maxy),
        z: randomNumberBetween(miny, maxy),
        mass: randomNumberBetween(1, 10),
        velocityX: randomNumberBetween(-vel, vel),
        velocityY: randomNumberBetween(-vel, vel),
        accelerationX: 0,
        accelerationY: 0,
        rotation: randomNumberBetween(-180, 180),
        color: tinycolor.random(),
    };
};

export const createRandomStaticParticleValues = (minx, maxx, miny, maxy) => {
    const props = createRandomParticleValues(minx, maxx, miny, maxy);
    props.velocityX = 0;
    props.velocityY = 0;
    return props;
};

export const createRandomStaticParticle = (x, y) => {
    const props = createRandomParticleValues(0, 100, 0, 100);
    props.x = x;
    props.y = y;
    props.velocityX = 0;
    props.velocityY = 0;
    return props;
};

