export class Particle {
    #x;

    #y;

    #z;

    #color;

    constructor({
        index,
        x,
        y,
        z,
        velocityX,
        velocityY,
        velocityZ,
        accelerationX,
        accelerationY,
        accelerationZ,
        radius,
        mass,
        color,
        alpha,
        rotation,
        drawFn,
        updateFn,
        colorFn,
        ...rest
    }) {
        this.props = rest;
        this.index = index || 0;

        // TODO remove separate x/y and just use a vector
        this.#x = x || 0;
        this.#y = y || 0;
        this.#z = z || 0;
        this.xHistory = [x];
        this.yHistory = [y];
        this.zHistory = [z];
        this.oX = x;
        this.oY = y;
        this.oZ = z;
        this.velocityX = velocityX || 0;
        this.velocityY = velocityY || 0;
        this.velocityZ = velocityZ || 0;
        this.accelerationX = accelerationX || 0;
        this.accelerationY = accelerationY || 0;
        this.accelerationZ = accelerationZ || 0;

        this.mass = mass || 1;
        this.radius = radius || 1;
        this.#color = color ? tinycolor(color) : tinycolor('white');
        this.rotation = rotation || 0;
        this.colorFn = colorFn;

        this.noiseValue = null;
    }

    get color() {
        if (this.colorFn) {
            // TODO type check to enforce string?
            return tinycolor(this.colorFn(this));
        }
        return this.#color;
    }

    set color(value) {
        this.#color = tinycolor(value);
    }

    get colorStr() {
        if (this.colorFn) {
            const res = this.colorFn(this);
            if (typeof res !== 'string') {
                console.warn('Particle color fn must return a string!');
                return '#ff0000';
            }
            return res;
        }
        return this.#color.toRgbString();
    }

    get x() {
        return this.#x;
    }

    set x(value) {
        this.#x = value;
        this.xHistory.unshift(value);
        if (this.xHistory.length > maxParticleHistory) {
            this.xHistory = this.xHistory.slice(0, maxParticleHistory);
        }
    }

    get y() {
        return this.#y;
    }

    set y(value) {
        this.#y = value;
        this.yHistory.unshift(value);
        if (this.yHistory.length > maxParticleHistory) {
            this.yHistory = this.yHistory.slice(0, maxParticleHistory);
        }
    }

    get z() {
        return this.#z;
    }

    set z(value) {
        this.#z = value;
        this.zHistory.unshift(value);
        if (this.zHistory.length > maxParticleHistory) {
            this.zHistory = this.zHistory.slice(0, maxParticleHistory);
        }
    }

    get velocity() {
        return new Vector(this.velocityX, this.velocityY, this.velocityZ);
    }

    set velocity({ x, y, z }) {
        this.velocityX = x;
        this.velocityY = y;
        this.velocityZ = z;
    }

    get acceleration() {
        return new Vector(this.accelerationX, this.accelerationY, this.accelerationZ);
    }

    set acceleration({ x, y, z }) {
        this.accelerationX = x;
        this.accelerationY = y;
        this.accelerationZ = z;
    }

    // Rotation angle to point in direction of velocity
    get heading() {
        return pointAngleFromVelocity(this);
    }

    // clone() {
    //     return Object.assign(Object.create(Object.getPrototypeOf(Particle)), this);
    // }

    reverseVelocityX() {
        this.velocityX *= -1;
    }

    reverseVelocityY() {
        this.velocityY *= -1;
    }

    updatePosWithVelocity() {
        this.x += this.velocity.x;
        this.y += this.velocity.y;
    }

    clearAcceleration() {
        this.acceleration = new Vector(0, 0);
    }

    applyForce(fVect) {
        const fV = fVect.div(this.mass);
        const aV = this.acceleration.add(fV);
        const pV = this.velocity.add(aV);
        this.acceleration = aV;
        this.velocity = pV;
    }

    gravity(g = 0) {
        const force = new Vector(0, g);
        this.applyForce(force);
    }

    weight(g = 0) {
        const gravity = new Vector(0, g);
        const force = gravity.mult(this.mass);
        this.applyForce(force);
    }

    wind(w = 0) {
        const force = new Vector(w, 0);
        this.applyForce(force);
    }

    // https://www.youtube.com/watch?v=WBdhAuWS6X8
    friction(mu = 0.1) {
        const normal = this.mass;
        const vfriction = this.velocity
            .normalize()
            .mult(-1)
            .setMag(mu * normal);
        this.applyForce(vfriction);
    }

    // https://www.youtube.com/watch?v=DxFDgOYEoy8
    drag(coefficent = 0.1) {
        const area = 1; // this.radius;
        const velUnit = this.velocity.normalize().mult(-1);
        const speed = this.velocity.magSq() * area * coefficent;
        const vdrag = velUnit.setMag(speed);
        this.applyForce(vdrag);
    }

    // https://www.youtube.com/watch?v=EpgB3cNhKPM
    // mode 1 is attract, -1 is repel
    // const attractor = { x: canvas.width / 2, y: canvas.height / 2, mass: 50, g: 1 };
    attract({ x, y, mass, g }, mode = 1, affectDist = 1000) {
        if (pointDistance({ x, y }, { x: this.x, y: this.y }) < affectDist) {
            const gravity = g || 1;
            const dir = new Vector(x, y).sub(new Vector(this.x, this.y));
            const distanceSq = clamp(50, 5000, dir.magSq());
            const strength = (mode * (gravity * (mass * this.mass))) / distanceSq;
            const force = dir.setMag(strength);
            this.applyForce(force);
        }
    }
}

export const forceGravity = (g = 0) => (p) => {
    const force = new Vector(0, g);
    p.applyForce(force);
};

export const forceWeight = (g = 0) => (p) => {
    const gravity = new Vector(0, g);
    const force = gravity.mult(p.mass);
    p.applyForce(force);
};

export const forceWind = (w = 0) => (p) => {
    const force = new Vector(w, 0);
    p.applyForce(force);
};

// https://www.youtube.com/watch?v=WBdhAuWS6X8
export const forceFriction = (mu = 0.1) => (p) => {
    const normal = p.mass;
    const force = p.velocity
        .normalize()
        .mult(-1)
        .setMag(mu * normal);
    p.applyForce(force);
};

// https://www.youtube.com/watch?v=DxFDgOYEoy8
export const forceDrag = (coefficent = 0.1) => (p) => {
    const area = 1; // p.radius;
    const velUnit = p.velocity.normalize().mult(-1);
    const speed = p.velocity.magSq() * area * coefficent;
    const force = velUnit.setMag(speed);
    p.applyForce(force);
};

// https://www.youtube.com/watch?v=EpgB3cNhKPM
// mode 1 is attract, -1 is repel
// const attractor = { x: canvas.width / 2, y: canvas.height / 2, mass: 50, g: 1 };

export const forceAttractor = (x, y, g = 1, mass = 100) => ({ x, y, g, mass });

export const forceAttract = (attractor, mode = 1, affectDist = 100) => (p) => {
    const { x, y, g, mass } = attractor;
    if (pointDistance({ x, y }, { x: p.x, y: p.y }) < affectDist) {
        const gravity = g || 1;
        const dir = new Vector(x, y).sub(new Vector(p.x, p.y));
        const distanceSq = clamp(50, 5000, dir.magSq());
        const strength = (mode * (gravity * (mass * p.mass))) / distanceSq;
        const force = dir.setMag(strength);
        p.applyForce(force);
    }
};

