export class ParticleSystem {
    constructor(boundsRect, updateFn, drawFn, particles = []) {
        this.particles = particles;
        this.boundsRect = boundsRect;
        this.updateFn = updateFn;
        this.drawFn = drawFn;

        // 1 = w/ forces
        // 2 = direct setMap x,y
        this.updateMode = 1;

        this.minx = this.boundsRect.x;
        this.maxx = this.boundsRect.x2;
        this.miny = this.boundsRect.y;
        this.maxy = this.boundsRect.y2;

        this.limits = {};
        this.forces = [];
        this.noiseFn = null;
        this.edgeFn = null;
    }

    add(particle) {
        this.particles.push(particle);
    }

    addForce(fn) {
        this.forces.push(fn);
    }

    addRandomInBounds() {
        const props = createRandomParticleValues(
            this.boundsRect.x,
            this.boundsRect.x2,
            this.boundsRect.y,
            this.boundsRect.y2
        );
        this.add(new Particle(props));
    }

    addRandomStaticInBounds() {
        const props = createRandomStaticParticleValues(
            this.boundsRect.x,
            this.boundsRect.x2,
            this.boundsRect.y,
            this.boundsRect.y2
        );
        this.add(new Particle(props));
    }

    map(fn) {
        this.particles = this.particles.map(fn);
    }

    scaleParticlePositions(scale = 1) {
        this.particles.forEach((p) => {
            p.x *= scale;
            p.y *= scale;
            p.z *= scale;
        });
    }

    runParticleForces(p) {
        let hasForce = false;
        if (this.noiseFn) {
            hasForce = true;
            const result = this.noiseFn(p.x, p.y);
            if (typeof result === 'number') {
                p.noiseValue = result; // * TAU;
                const force = uvFromAngle(p.noiseValue);
                // console.log(p.noiseValue, force.x);
                p.applyForce(force);
            } else {
                // console.log('result is obj', result);
                console.warn('update or noise fn result is an object! use updateMode=2');
            }
        }
        this.forces.forEach((forceFn) => forceFn(p));
        if (this.limits.hasOwnProperty('velocity')) {
            p.velocity = p.velocity.limit(this.limits.velocity);
        }
        p.updatePosWithVelocity();
        p.clearAcceleration();

        if (this.updateFn) this.updateFn(p, this);
        if (this.edgeFn) this.edgeFn(p);
    }

    runParticleDirect(p) {
        if (this.noiseFn) {
            const result = this.noiseFn(p.x, p.y, p.z);
            p.x = result.x;
            p.y = result.y;
            p.z = result.z;
        }
        if (this.updateFn) this.updateFn(p, this);
        if (this.edgeFn) this.edgeFn(p);
    }

    update() {
        this.particles.forEach((p) => {
            if (this.updateMode === 1) this.runParticleForces(p);
            if (this.updateMode === 2) this.runParticleDirect(p);
        });
    }

    updateParticle(p) {
        if (this.updateMode === 1) this.runParticleForces(p);
        if (this.updateMode === 2) this.runParticleDirect(p);
    }

    draw() {
        this.particles.forEach((p) => {
            if (this.drawFn) this.drawFn(p, this);
        });
    }

    iterate(n = 1) {
        for (let i = 0; i < n; i++) {
            this.update();
        }
    }

    getParticlePositionsPA() {
        return this.particles.reduce((acc, p) => {
            acc.push([p.x, p.y]);
            return acc;
        }, []);
    }

    getParticlePositionsPO() {
        return this.particles.reduce((acc, p) => {
            acc.push({ x: p.x, y: p.y });
            return acc;
        }, []);
    }

    edgeBounce(p) {
        if (p.x + p.radius > this.maxx) {
            p.reverseVelocityX();
            p.x = this.maxx - p.radius;
        }
        if (p.x - p.radius < this.minx) {
            p.reverseVelocityX();
            p.x = this.minx + p.radius;
        }
        if (p.y + p.radius > this.maxy) {
            p.reverseVelocityY();
            p.y = this.maxy - p.radius;
        }
        if (p.y - p.radius < this.miny) {
            p.reverseVelocityY();
            p.y = this.miny + p.radius;
        }
    }

    edgeWrap(p) {
        if (p.x + p.radius > this.maxx) {
            p.x = this.minx + p.radius;
        } else if (p.x - p.radius < this.minx) {
            p.x = this.maxx - p.radius;
        }
        if (p.y + p.radius > this.maxy) {
            p.y = this.minx + p.radius;
        } else if (p.y - p.radius < this.miny) {
            p.y = this.maxy - p.radius;
        }
    }

    createParticlePath(particle, length = 100, bounds) {
        const coordinates = [];
        for (let i = 0; i < length; i++) {
            this.updateParticle(particle);
            coordinates.push([particle.x, particle.y]);
            if (bounds && !bounds.contains(particle)) {
                break;
            }
        }
        return coordinates;
    }
}

export const createSimpleParticleSystem = (rcanvas, bounds, frequency = 0.002, amplitude = 1, velocity = 5) => {
    const particles = new ParticleSystem(bounds);
    particles.updateMode = 1;
    particles.noiseFn = (x, y) => rcanvas.noise(x, y, 0, frequency, amplitude);
    particles.limits.velocity = velocity;
    return particles;
};
