import tinycolor from 'tinycolor2';

import {
    bicPenBlue,
    greyValueToRGB,
    Palette,
    palettes,
    paperWhite,
    rotateHue,
    warmGreyDark,
    warmPink,
    warmWhite,
} from '../color/palettes';
import { CanvasGridLayout } from '../v2/RCanvas';

import { simplexNoise2d, simplexNoise3d } from '../v2/fieldsAndAttractors';
import { mapRange } from '../math/math';
import { Terrain, getHeightAtPosition } from '../v2/Terrain';
import {
    randomBoolean,
    randomChance,
    randomNormalNumberBetween,
    randomNormalWholeBetween,
    randomNumberBetween,
    randomValue,
    randomWholeBetween,
} from '../math/random';
import { segmentsFromPoints } from '../math/segments';
import { QuadTree } from '../v2/QuadTree';
import { getPointsForAreaFill, poissonDiscVariable } from '../v2/poissonDisc';
import { createRandomStaticParticle, ParticleSystem, Particle } from '../v2/ParticleSystem';
import { drawFilledRakeRect, drawRakeStroke, getFiberStrokeMid } from '../v2/rakeStroke';
import { bigWetDaub } from '../v2/watercolor';

function getFeatureString(value) {
    if (value < 0.3) return 'low';
    if (value < 0.8) return 'medium';
    return 'high';
}

export const terrainQuilt2 = (sketch) => {
    window.$fxhashFeatures = {
        colorful: getFeatureString(randomValue()) === 'medium',
        thickStrokes: getFeatureString(randomValue()) === 'medium',
        smooth: getFeatureString(randomValue()) === 'medium',
        particleEscapeBounds: getFeatureString(randomValue()) === 'low',
    };

    if (!sketch.fxHashMode) console.log(window.$fxhashFeatures);

    const sketchSize = 1000;

    const config = {
        name: 'terrain-quilt-2',
        edition: 1,
        // width: scaleValueToRatio(ratio.golden)(sketchSize),
        width: sketchSize,
        height: sketchSize,
    };

    const { datGUI, rcanvas } = sketch;

    const margin = sketchSize * 0.05;

    // const paletteList = [palettes['80s_pop'], palettes['60s_psyc'], palettes['70s'], palettes['90s']];
    const palette = new Palette(); // oneOf(paletteList)

    const foregroundColor = warmGreyDark.clone().lighten(20);

    const bgColor1 = warmPink.clone();
    const bgColor2 = palette.darkest.complement().desaturate(50).lighten(60);
    const backgroundColor = tinycolor.mix(bgColor1, bgColor2, 50);

    let layout;
    let quadTree;
    let quadTreeRects;
    let particles;
    let terrain;
    let simplexFn;

    let counter = 0;
    const maxLoops = 10;
    let currentLoop = 0;
    let time = 0;
    const timeLoopIncrement = randomNumberBetween(1, 5);

    const settings = {
        amplitude: 1,
        frequency: randomNumberBetween(1, 8) * 0.001,

        terrainDetail: randomWholeBetween(4, 8),
        terrainRoughness: randomWholeBetween(5, 7) * 0.1,
        numQuadtreeInitPoints: randomWholeBetween(50, 500),
        poissonOnNoise: true,
        poissonMinRadius: 2, // randomWholeBetween(2, 5),
        poissonMaxRadius: randomNormalWholeBetween(5, 10),
        minLineWeight: 1,
        maxLineWeight: window.$fxhashFeatures.thickStrokes
            ? randomNumberBetween(5, 15)
            : randomNormalNumberBetween(1, 5),
        minLineLength: 3,
        maxLineLength: randomNormalNumberBetween(10, 30),
        minStokeWeight: randomNormalNumberBetween(0.1, 1),
        maxStokeWeight: randomNormalNumberBetween(1, 3),
        strokeColorVarianceAmount: randomNormalNumberBetween(10, 30),
        strata: randomNormalWholeBetween(100, 200),
        rectOffsetMult: 5,
        optShowSun: randomChance(),

        terrainInfluence: window.$fxhashFeatures.smooth ? 0 : randomWholeBetween(1, 3),
        allowParticleBoundsEscape: window.$fxhashFeatures.particleEscapeBounds,
        optColorful: window.$fxhashFeatures.colorful,
    };

    const getTheta = (x, y) => {
        const { theta } = getHeightAtPosition(terrain, layout.bounds, x - layout.bounds.x, y - layout.bounds.y);
        const noise = simplexFn(x, y, time);
        const tweight = settings.terrainInfluence;
        return (theta * tweight + noise) / (tweight + 1);
    };

    const onSettingsChange = (setting) => (newValue) => {
        console.log(setting, newValue);
        console.log(JSON.stringify(settings));
        reset();
    };

    const setupSetting = (key, min = 0, max = 100, step = 1) => {
        if (!datGUI) return;
        const c = datGUI.add(settings, key, min, max, step);
        c.onFinishChange(onSettingsChange(key));
    };

    const setupDatGUI = () => {
        setupSetting('allowParticleBoundsEscape', false, true, 1);
        setupSetting('amplitude', 0.1, 3, 0.1);
        setupSetting('frequency', 0.001, 1, 0.001);
        setupSetting('terrainInfluence', 0, 10, 1);
        // setupSetting('terrainDetail', 1, 8, 1);
        // setupSetting('terrainRoughness', 0.1, 0.7, 0.1);
        // setupSetting('numQuadtreeInitPoints', 20, 200, 1);
        setupSetting('poissonMinRadius', 2, 10, 1);
        setupSetting('poissonMaxRadius', 20, 100, 1);
        setupSetting('minLineWeight', 1, 10, 1);
        setupSetting('maxLineWeight', 10, 100, 1);
        setupSetting('minLineLength', 1, 20, 1);
        setupSetting('maxLineLength', 20, 100, 1);
        setupSetting('maxStokeWeight', 1, 10, 10);
        setupSetting('strokeColorVarianceAmount', 0, 50, 1);
    };

    const setup = ({ first }) => {
        if (first) {
            layout = new CanvasGridLayout(rcanvas.width, rcanvas.height, margin, 1, 1, 0);
            setupDatGUI();
        }

        // simplexFn = simplexNoise2d(settings.frequency, settings.amplitude, false);
        simplexFn = simplexNoise3d(settings.frequency, settings.amplitude, false);
        terrain = new Terrain(settings.terrainDetail, settings.terrainRoughness);
        terrain.generate();

        quadTree = new QuadTree(layout.bounds, 5);

        getPointsForAreaFill(layout.fullBounds, 5, 50, 0.01).forEach((p) => {
            quadTree.insert(p);
            // rcanvas.circle(p.x, p.y, 1);
        });
        quadTreeRects = quadTree.flatten([]).map((q) => q.boundary);

        particles = new ParticleSystem(layout.bounds, null, null);
        particles.noiseFn = getTheta;
        // particles.limits.velocity = 1;

        if (first) {
            rcanvas.background(backgroundColor);
            rcanvas.noStroke();
            getPointsForAreaFill(layout.fullBounds, 2, 4, 0.001).forEach(({ x, y }) => {
                const pSize = randomNormalNumberBetween(0.5, 2);
                rcanvas.fill(palette.oneOf().clone().desaturate(randomNormalWholeBetween(50, 100)).setAlpha(0.1));
                rcanvas.circle(x, y, pSize);
            });

            let pStep = randomNormalNumberBetween(3, 5);
            for (let { x } = layout.bounds; x < layout.bounds.x2; x += pStep) {
                for (let { y } = layout.bounds; y < layout.bounds.y2; y += pStep) {
                    const pSize = randomNormalNumberBetween(0.5, 2);
                    rcanvas.fill(palette.oneOf().clone().desaturate(randomNormalWholeBetween(50, 100)).setAlpha(0.4));
                    rcanvas.circle(x, y, pSize);
                    pStep = randomNormalNumberBetween(3, 5);
                }
            }
        }

        // rcanvas.showNoise(layout.fullBounds, getTheta, 200);

        // if (settings.optColorful) rcanvas.blendMode('multiply');
    };

    const reset = () => {
        setup({ first: false });
        sketch.restart();
    };

    const getArrayValue = ({ x, y }, arry) => {
        const pointY = y + getTheta(x, y) * settings.strata;
        return arry[Math.round(pointY / settings.strata) % arry.length]; /// randomNormalNumberBetween(100, 150)
    };

    const distanceFn = (sample) => {
        if (settings.poissonOnNoise) {
            const theta = simplexFn(sample.x, sample.y, time);
            return Math.abs(theta);
        }
        return randomNumberBetween(0.1, 0.9);
    };

    const varyStrokeWeight = (strokeIdx) => randomWholeBetween(settings.minStokeWeight, settings.maxStokeWeight);

    const varyStrokeColor = (strokeColor) => (strokeIdx) =>
        rotateHue(
            strokeColor,
            randomNumberBetween(settings.strokeColorVarianceAmount * -1, settings.strokeColorVarianceAmount),
            randomNumberBetween(settings.strokeColorVarianceAmount * -1, settings.strokeColorVarianceAmount),
            randomNumberBetween(settings.strokeColorVarianceAmount * -1, settings.strokeColorVarianceAmount)
        );

    const varyOnSegment = (strokeColor) => (segLen, segIdx, segment) => {
        // const noise = simplexFn(segment.start.x, segment.start.y);
        // const alpha = 1; // mapRange(0.75, 1, -1, 1, noise);
        const segmentColor = tinycolor.mix(
            strokeColor.clone().desaturate(50).darken(30).setAlpha(0),
            strokeColor,
            (segIdx / segLen) * 100
        );
        return segmentColor;
    };

    const showWaterBlob = () => {
        rcanvas.blendMode('multiply');
        const point = layout.bounds.randomPointInside();
        bigWetDaub(
            rcanvas,
            point.x,
            point.y,
            randomWholeBetween(50, 200),
            palette.brightest.clone().setAlpha(0.1),
            20,
            4
        );
        rcanvas.blendMode();
    };

    const draw = () => {
        // rcanvas.blendMode('multiply');

        const rect = quadTreeRects[counter];

        // const rectmidtheta = getTheta(rect.mx, rect.my) * settings.rectOffsetMult;
        // rect.translate(rectmidtheta, rectmidtheta);

        const ppoints = poissonDiscVariable(
            rect,
            settings.poissonMinRadius,
            settings.poissonMaxRadius,
            distanceFn,
            1,
            30
        ).fill();

        const particleBounds = settings.allowParticleBoundsEscape && randomBoolean() ? null : rect;

        ppoints.forEach((p) => {
            const theta = getTheta(p.x, p.y);

            const colorA = getArrayValue(p, palette.colors) || palette.oneOf().clone();

            let color = settings.optColorful || randomChance() ? varyStrokeColor(colorA)() : foregroundColor.clone();
            const colorB = color.clone().saturate(50).lighten(20);

            const mixPercent = mapRange(-1, 1, 0, 100, theta);
            color = tinycolor.mix(color, colorB, mixPercent);

            const alpha = mapRange(-1, 1, 0.2, 1, theta);
            const saturation = mapRange(-1, 1, 50, 0, theta);
            color.desaturate(saturation).setAlpha(alpha);

            rcanvas.stroke(color);

            const length = mapRange(0, 1, settings.minLineLength, settings.maxLineLength, Math.abs(theta));

            const pt = new Particle(createRandomStaticParticle(p.x, p.y));
            const pathSegments = particles.createParticlePath(pt, length, particleBounds);

            const strokeThickness = randomWholeBetween(settings.minLineWeight, settings.maxLineWeight);
            const strokeSpacing = randomNumberBetween(0.25, 3);
            const strokeFringe = randomNumberBetween(5, 20);

            const expanded = getFiberStrokeMid(
                segmentsFromPoints(pathSegments),
                strokeThickness,
                strokeSpacing,
                strokeFringe
            );

            // const segs = segmentsFromPoints(pathSegments);
            // const weight = mapRange(0, 1, minLineWeight, maxLineWeight, Math.abs(theta));
            // rcanvas.strokeWeight(weight);
            // drawLineSegs(rect, segs);

            drawRakeStroke(rcanvas, expanded, varyStrokeWeight, varyStrokeColor(color), varyOnSegment(color));

            // drawPoint(p.x, p.y, getTheta(p.x, p.y), 10, colorA, colorA.clone().darken(20));
        });

        // if (randomNumberBetween(0, 3) > 2.9) showWaterBlob();

        const remaining = counter++ < quadTreeRects.length - 1;
        if (remaining) {
            return true;
        }
        const loopsRemaining = currentLoop++ < maxLoops;
        if (!loopsRemaining) {
            console.log('Done!');
            return false;
        }
        counter = 0;
        time += timeLoopIncrement;
        setup({ first: false });
        return true;
        // return false;
    };

    return {
        config,
        setup,
        draw,
    };
};
